  // --- PC-56 TENANT-1b-3 · W155 Farmer 360 ---
  'f360.title': 'સભ્ય 360',
  'f360.heading': 'ખેડૂત 360 — {name}',
  'f360.subtitle': 'આ સભ્ય વિશે તમારી સંસ્થા જે જાણે છે, દર વખતે ખોલતાં તાજું જોડાય છે. આ પાનું ખોલવું નોંધાય છે.',
  'f360.back': 'સભ્ય પર પાછા',
  'f360.restricted': 'આ દૃશ્ય માટે સભ્ય-360 પરવાનગી જોઈએ — તે તમારા કન્સોલનું સૌથી ઊંડું વ્યક્તિગત દૃશ્ય છે, તેથી સૌથી સીમિત પરવાનગી ધરાવે છે. કામ માટે જરૂરી હોય તો વ્યવસ્થાપક પાસે માંગો.',
  'f360.loadError': 'આ 360 પૂરું જોડાઈ શક્યું નથી. એક કે વધુ વાચન નિષ્ફળ ગયાં, અને અધૂરી માહિતી ક્યારેય પૂર્ણ ગણાવીને દેખાડાતી નથી — તેથી કંઈ દેખાડાયું નથી. કૃપા કરીને ફરી પ્રયાસ કરો.',
  'f360.tile.income': 'મળેલી ખેતી આવક (12 મહિના)',
