  'f360.tile.creditKycNo': 'દરેક સક્રિય ભૂમિકા પર KYC પૂર્ણ નથી',
  'f360.tile.creditAbsent': 'અમે ધિરાણ-તૈયારીનો આંક આપતા નથી. કોઈ ધિરાણકર્તાએ અમારી સાથે નિયમ નક્કી કર્યો નથી, અને સભ્યને લોન-તૈયાર કહીને બેન્ક ના પાડે તો તેમનો એક દિવસનો રોજ જાય છે. બેન્કરને ઉપરના પુરાવા આપો.',
