  'f360.advisory': 'આ સભ્યને આગળ શું મદદ કરશે',
  'f360.advisoryAbsent': 'હજી ઉપલબ્ધ નથી, અને અનુમાન કરવાને બદલે જાણીજોઈને ખાલી. ઉપયોગી સૂચનો માટે સંગ્રહાયેલા, ન વેચાયેલા માલનો રેકોર્ડ જોઈએ, જે અહીં નથી. જ્યારે આવશે, સૂચનો તમારા કર્મચારીઓ સુધી પહોંચશે જેથી સભ્ય તે વિશ્વાસુ વ્યક્તિ પાસેથી સાંભળે — ક્યારેય સ્વયંસંચાલિત સંદેશ તરીકે નહીં.',
  'f360.dignity': 'પહોંચ અને ગૌરવ',
  'f360.dignityNote': 'આ પાનું આ સભ્યની સેવા માટે છે, દેખરેખ માટે નહીં. તેઓ ક્યારેય પોતાનો આખો રેકોર્ડ માંગી શકે છે, અને તે બરાબર આવો જ દેખાય છે — કંઈ છુપાવેલું નહીં, કંઈ એવું નહીં જે દેખાડવામાં અમને સંકોચ થાય.',
  'f360.recorded': 'આ દૃશ્ય {at} ના રોજ તમારા નામ સાથે નોંધાયું.',
  'f360.nothingOnFile': 'તમારી સંસ્થા પાસે આ સભ્યની જમીન, ઋતુઓ, યોજના લાભ કે આવક હજી નોંધાયેલી નથી. આ રેકોર્ડની ખામી છે, તેમની ખેતીની નહીં.',

  // --- PC-56 TENANT-1b-4 · W156 bulk member import ---
