  'limport.issueSuggestion': 'સૂચન: {suggestion} (કંઈ પણ આપોઆપ લાગુ થતું નથી)',
  'limport.validate': 'દરેક પંક્તિ ચકાસો',
  'limport.confirm': '{n} ડ્રાફ્ટ બનાવો',
  'limport.nothingToCreate': 'બનાવવા જેવું કંઈ નથી — દરેક ઉપયોગી પંક્તિ પહેલેથી લિસ્ટેડ છે. તમારી સૂચિ અદ્યતન છે.',
  'limport.cancel': 'રદ કરો',
  'limport.seeDrafts': 'ડ્રાફ્ટ જુઓ →',
  'limport.ok.validated': 'ચકાસણી પૂરી. કંઈ બન્યું નથી — નીચેની ત્રિઆજ કહે છે આ ફાઇલ શું કરશે.',
  'limport.ok.confirmed': 'ઇમ્પોર્ટ ચાલે છે. દરેક પંક્તિ ડ્રાફ્ટ બનીને QC જાય છે; જોવા માટે રિફ્રેશ કરો.',
  'limport.ok.cancelled': 'અપલોડ રદ. કંઈ બન્યું નથી.',
  'limport.error.validate': 'ચકાસણી ચાલી નહીં. કંઈ બન્યું નથી.',
  'limport.error.confirm': 'આ અપલોડ આગળ વધી ગયું છે — ક્યાં છે તે જોવા રિફ્રેશ કરો. કંઈ પણ બે વાર ઇમ્પોર્ટ થયું નથી.',
  'limport.error.cancel': 'અપલોડ રદ ન થઈ શક્યું — વર્તમાન સ્થિતિ માટે રિફ્રેશ કરો.',
