  'od.snapshot.beforeSnapshot': 'આ ઓર્ડર ત્યારે બન્યો જ્યારે ચાર્જ-નિયમો તેની સાથે નોંધાતા નહોતા (હવેથી નોંધાય છે). ઉપરની રકમો બરાબર એ જ છે જે લેવાઈ; તેની પાછળના નિયમો ફરી કાઢી શકાતા નથી, તેથી અહીં કંઈ અનુમાન કરાયું નથી.',
