  // PC-56 TENANT-4a · W143/W144 — the ORGANISATION's wallet and its ledger.
  'wal.title': 'વૉલેટ',
  'wal.intro': 'Tamari sanstha na tran khata (main · commission · hold), badha append-only hash-chained ledger par aadharit. Aa page par darek aankdo tamari potani ledger entries no jodo chhe — koi cached balance nahi.',
  'wal.notYourPersonalWallet': 'Aa sanstha na paisa chhe. Tamaru vyaktigat wallet member app ma chhe; te alag khatu chhe ane aa sathe kadi bhelu thatu nathi.',
  'wal.restricted': 'Sanstha na balance jova mate wallet.org_view paravangi joie. Admin ne kaho — ledger par kai asar nathi.',
  'wal.loadError': 'Balance load na thaya. Ledger surakshit chhe ane payout samay par chale chhe. Fari prayatna karo.',
  'wal.frozen': 'freeze karel',
  'wal.account.main': 'main',
  'wal.account.commission': 'commission',
  'wal.account.hold': 'hold',
  'wal.accountMeaning.main': 'Have kharchi shakay — dudh bill, yojana vitaran ane loan vitaran ahi thi apay chhe.',
  'wal.accountMeaning.commission': 'Tamari sanstha e kamayelu commission, order pooru thay tyare jama ane refund thay to pachu.',
  'wal.accountMeaning.hold': 'Vivaad same rokel paisa. Aaje aa khata ma kai lakhatu nathi — niche juo.',
  'wal.state.reconciled': 'ledger ane cache sahmat',
  'wal.state.drifted': 'cache asahmat — ledger batavyu',
  'wal.state.never_used': 'kadi vaparayu nathi',
  'wal.driftNotice': 'Cached balance {cached} kahe chhe, farak {drift}. Upar no aankdo ledger no potano jodo chhe, je asli chopdo chhe. Platform reconciliation aa pakdi lese; kai gumayu nathi.',
  'wal.holdNoFreezePath': 'Aa shunya chhe karan ke KOI code path sanstha na paisa freeze karto nathi. Jyare kharidnar vivaad uthave, platform teno aakho bhugtan escrow ma rakhe chhe jya sudhi vivaad band na thay — tamara wallet par per-line freeze nathi.',
  'wal.holdFrozen': 'Aa khulla vivaad same rokel paisa chhe, ledger ma nondhayel.',
  'wal.holdNeverWritten': 'Hold khata ma ek pan entry nathi — ledger banya pachi kadi lakhayu nathi.',
  'wal.gapsTitle': 'Banyu nathi — ane naam thi kahyu chhe, dhong karyo nathi',
  'wal.gap.add_funds': 'UPI thi paisa nakhva: platform ma sanstha mate top-up have kyay nathi. Evu form je rakam le ane mokalva ni jagya na hoy te dekhaay ke paisa gaya — tethi button nathi.',
  'wal.gap.payout_bank_change': 'Payout bank khatu badalvu (owner + checker + 24 kalak no cooling period) banyu nathi. Aaje payout khata vyaktigat sabhyo na hoy chhe, KYC thi verify. Control saachu na thay tya sudhi ahi apashe nahi.',
  'wal.gap.tenant_hold_freeze': 'Vivaad same bhugtan no bhag freeze karvo banyo nathi. Teni jagya e escrow kharidnar no aakho bhugtan order mate roke chhe, ane vivaad ni screen e kahe chhe.',
  'wal.todayTitle': 'Aaj ni halchal',
  'wal.todayEmpty': 'Aaje sanstha wallet mathi have kai pasar thayu nathi. Vechan, payout ane fee jem thay tem ahi dekhashe.',
  'wal.healthTitle': 'Ledger ni tandurasti',
  'wal.health.cached_vs_ledger': 'Tamara cached balance tamari potani entries na joda sathe male chhe',
  'wal.health.own_chain': 'Tamara khata ni hash chain, entry-dar-entry fari ganel',
  'wal.health.platform_recon': 'Aakha platform nu zero-sum ane gateway reconciliation',
  'wal.healthState.ok': 'chakasyu — barabar',
  'wal.healthState.attention': 'dhyan joie',
  'wal.healthState.unverifiable': 'chakasi shakayu nahi',
  'wal.healthState.not_ours_to_assert': 'platform chalave chhe',
  'wal.healthPlatformNote': 'Zero-sum ane gateway reconciliation aakha ledger par chale chhe, je darek sanstha vhenche chhe. Platform teno chalave chhe ane teni jawabdari le chhe; aa console biji sansthao na paisa vishe "0 breaks" fari kaheshe nahi. Je aa chakase chhe te upar chhe: tamara balance tamari entries sathe, ane tamari chain.',
  'wal.chain.intact': 'akhand — darek entry potana nondhayel maan sathe male chhe ane darek link joday chhe',
  'wal.chain.headMismatch': 'chain saaf chale chhe pan khata no head pointer teni chhelli entry sathe asahmat chhe — platform ne janavo',
  'wal.chain.hashMismatch': 'ek entry potana nondhayel maan sathe malti nathi — turant platform ne janavo',
  'wal.chain.chainBreak': 'ek link agal ni entry sathe malto nathi — turant platform ne janavo',
  'wal.chain.incomplete': 'ek vakhat ma chalav vay tethi vadhare entries chhe, tethi aa nathi chakasayu, akhand nahi',
  'wal.chain.empty': 'have koi entry nathi, tethi chakasva jevu kai nathi',
  'wal.escrowTitle': 'Escrow (platform pase, have tamaru nahi)',
  'wal.escrowHeld': 'Tamara {count} chalu order na kharidnar na paisa. Delivery pakki thay tya sudhi te platform escrow ma rahe chhe ane tamara balance no bhag nathi. Escrow koi kharchtu nathi, ame pan nahi.',
  'wal.escrowNone': 'Have tamara mate koi kharidnar na paisa rokel nathi.',
  'wal.escrowBasis': 'Aadhar: tamari sanstha ni id dharavti escrow entries no net — capture umere chhe, pooru thavu ane refund ghatade chhe. Ledger nu ganit, cached aankdo nahi.',
  'wal.openLedger': 'Ledger kholo — darek entry',
  'wal.ledgerTitle': 'Wallet vyavahar',
  'wal.ledgerIntro': 'Ledger, fakt umeray chhe: darek vyapar ghatna ek vyavahar chhe jeni entries no jodo shunya chhe. Filter tarikh-badh chhe ane default chhella 30 divas.',
  'wal.ledgerEmpty': 'Sanstha wallet mathi pasar thata vechan, payout, fee ane refund jem thay tem ahi dekhashe.',
  'wal.ledgerEmptyFiltered': 'Aa gala ma aa filter sathe koi entry malti nathi. Tarikh vadharo athva filter kadho — ledger das varsh rakhe chhe, mahine pramane vahenchayel.',
  'wal.ledgerLoadError': 'Ledger view load na thayu. Ledger pote append-only ane surakshit chhe. Fari prayatna karo.',
