  'stl.requestedAt': 'Band karva ni vinanti {at}',
  'stl.decidedAt': 'Nirnay {at}',
  'stl.twoHumans': 'Cycle band karva ma sada be manas joie: ek vinanti kare, biji manjuri aape. Evi koi rakam nathi jena niche ek vyakti puro hoy — cycle koina rozgaar no galo chhe, fakt aankdo nahi.',
  'stl.closeTitle': 'Aa cycle band karo',
