  'stl.orgStatementTitle': 'Sanstha nu mahina nu statement',
  'stl.orgStatementDerived': 'Aa statement darek vakhat tamara append-only ledger mathi BANAVAY chhe — sharu no balance, prakar pramane halchal, chhello balance — ane aa tran no mel na hoy to jari thatu j nathi. Ena koi statement number nathi, karan ke te sacheli copy nathi: jene te j ledger rows hoy te tene barabar evu j fari banavi shake, je file ma rakhel PDF thi vadhu majbut guarantee chhe — kem ke te PDF ne ledger pachi khoto pan thabhavi shake.',
